Here is the root cause:
The VBIOS record-chain walking loops in both bios_parser.c and bios_parser2.c use unbounded `for(;;)` loops that rely solely on a terminating record (0xFF record_type) or zero record_size to exit. A malformed VBIOS image lacking the terminator causes these loops to iterate indefinitely, leading to excessive iterations (potentially hundreds of thousands) and out-of-bounds memory reads when the loop continues past the end of the BIOS image.

Here is the patch:

 static enum bp_result bios_parser_get_i2c_info(struct dc_bios *dcb,
 	struct graphics_object_id id,
 	struct graphics_object_i2c_info *info)
 {
 	uint32_t offset;
 	ATOM_OBJECT *object;
 	ATOM_COMMON_RECORD_HEADER *header;
 	ATOM_I2C_RECORD *record;
 	struct bios_parser *bp = BP_FROM_DCB(dcb);
+	int i;

 	if (!info)
 		return BP_RESULT_BADINPUT;

 	object = get_bios_object(bp, id);

 	if (!object)
 		return BP_RESULT_BADINPUT;

 	offset = le16_to_cpu(object->usRecordOffset)
 			+ bp->object_info_tbl_offset;

-	for (;;) {
+	for (i = 0; i < BIOS_MAX_NUM_RECORD; i++) {
 		header = GET_IMAGE(ATOM_COMMON_RECORD_HEADER, offset);

 		if (!header)
 			return BP_RESULT_BADBIOSTABLE;

 		if (LAST_RECORD_TYPE == header->ucRecordType ||
 			!header->ucRecordSize)
 			break;

 		if (ATOM_I2C_RECORD_TYPE == header->ucRecordType
 			&& sizeof(ATOM_I2C_RECORD) <= header->ucRecordSize) {
 			/* get the I2C info */
 			record = (ATOM_I2C_RECORD *) header;

 			if (get_gpio_i2c_info(bp, record, info) == BP_RESULT_OK)
 				return BP_RESULT_OK;
 		}

 		offset += header->ucRecordSize;
 	}

 	return BP_RESULT_NORECORD;
 }


